def get_epub_metadata(epub_path, **_extra):
    import json, os, datetime, hashlib, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_epub_metadata"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        rows = _load("request_logs.json")
        if isinstance(rows, list):
            return "request_logs.json", rows
        rows = _load("request_log.json")
        if isinstance(rows, list):
            return "request_log.json", rows
        return "request_logs.json", []

    def _log(status, code=None, message=None, extra=None):
        fname, logs = _ensure_request_log()
        rid = "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    def _norm_path(p):
        s = str(p).strip()
        s = re.sub(r"[\\/]+", "/", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _path_hash(p):
        return hashlib.sha256(_norm_path(p).lower().encode("utf-8")).hexdigest()

    def _filename_from_path(p):
        s = str(p).strip()
        for sep in ("#", "?"):
            if sep in s:
                s = s.split(sep, 1)[0]
        base = os.path.basename(s.rstrip("/"))
        return base or None

    def _gen_id(prefix, existing_rows):
        used = set()
        for r in existing_rows:
            if isinstance(r, dict) and isinstance(r.get("id"), str):
                used.add(r["id"])
        for _ in range(50):
            cand = prefix + "_" + hashlib.sha256(f"{prefix}|{time.time_ns()}|{os.getpid()}".encode("utf-8")).hexdigest()[:24]
            if cand not in used:
                return cand
        return prefix + "_" + hashlib.sha256(f"{prefix}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    # Validate
    if not isinstance(epub_path, str) or not epub_path.strip():
        _log("error", "VALIDATION_ERROR", "epub_path is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "epub_path is required and must be a non-empty string", param="epub_path")

    epub_path = epub_path.strip()
    h = _path_hash(epub_path)

    # Resolve to documents.source_path (doc_type='epub') by hash OR exact path OR by id (common client usage)
    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []

    doc = None
    for r in docs:
        if isinstance(r, dict) and r.get("doc_type") == "epub" and r.get("source_path_hash") == h:
            doc = r
            break
    if doc is None:
        for r in docs:
            if isinstance(r, dict) and r.get("doc_type") == "epub" and r.get("source_path") == epub_path:
                doc = r
                break
    if doc is None:
        for r in docs:
            if isinstance(r, dict) and r.get("doc_type") == "epub" and r.get("id") == epub_path:
                doc = r
                break

    created = False
    if doc is None:
        # Create a registered document row (offline: we don't check filesystem accessibility)
        doc_id = _gen_id("doc", docs)
        now = _now()
        doc = {
            "id": doc_id,
            "doc_type": "epub",
            "source_path": epub_path,
            "source_path_hash": h,
            "filename": _filename_from_path(epub_path),
            "title": None,
            "author": None,
            "language": None,
            "page_count": None,
            "file_size_bytes": None,
            "sha256": None,
            "status": "registered",
            "ingest_error": None,
            "created_at": now,
            "updated_at": now,
        }
        docs.append(doc)
        _save("documents.json", docs)
        created = True

    # If deleted, treat as not found
    if doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", "document is deleted", {"document_id": doc.get("id")})
        return _err("NOT_FOUND", "EPUB path cannot be resolved or file is not accessible", path=epub_path)

    # Simulate ingestion into metadata store using any existing metadata rows; otherwise set error (offline cannot parse files)
    metas = _load("document_metadata.json")
    if not isinstance(metas, list):
        metas = []

    existing_doc_metas = [m for m in metas if isinstance(m, dict) and m.get("document_id") == doc.get("id")]
    # If document already ready/error, just return formatted from store
    if doc.get("status") in ("ready", "error") and existing_doc_metas:
        # Build formatted output and also return structured metadata
        def _fmt(rows):
            # group by namespace
            out_lines = []
            grouped = {}
            for r in rows:
                ns = r.get("namespace") or "custom"
                grouped.setdefault(ns, []).append(r)
            for ns in sorted(grouped.keys()):
                out_lines.append(f"[{ns}]")
                for r in sorted(grouped[ns], key=lambda x: (str(x.get('key') or ""), str(x.get('id') or ""))):
                    k = r.get("key")
                    v = r.get("value")
                    if v is None and r.get("value_json") is not None:
                        try:
                            v = json.dumps(r.get("value_json"), ensure_ascii=False)
                        except Exception:
                            v = str(r.get("value_json"))
                    out_lines.append(f"{k}: {'' if v is None else v}")
                out_lines.append("")
            return "\n".join(out_lines).rstrip() + ("\n" if out_lines else "")

        payload = {
            "data": {
                "document": doc,
                "metadata": existing_doc_metas,
                "formatted": _fmt(existing_doc_metas),
            },
            "meta": {"created_document": created, "timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000)},
        }
        _log("ok", None, None, {"document_id": doc.get("id")})
        return payload

    # Perform a stateful "ingest metadata" pass:
    # transition registered/error -> ingesting -> ready OR error
    transitions = {
        "registered": ["ingesting", "deleted"],
        "ingesting": ["ready", "error", "deleted"],
        "ready": ["error", "deleted"],
        "error": ["ingesting", "deleted"],
        "deleted": []
    }

    cur = doc.get("status")
    now = _now()

    if cur in ("registered", "error"):
        if "ingesting" not in transitions.get(cur, []):
            _log("error", "INVALID_TRANSITION", "illegal transition to ingesting", {"from_status": cur, "to_status": "ingesting"})
            return _err("INVALID_TRANSITION", "Illegal status transition for ingestion", from_status=cur, to_status="ingesting")
        doc["status"] = "ingesting"
        doc["updated_at"] = now
        _save("documents.json", docs)
        cur = "ingesting"

    # In offline datastore mode: we can't extract from file; we mark ready if there is at least some metadata or pages already extracted,
    # otherwise mark error with message.
    pages = _load("document_pages.json")
    if not isinstance(pages, list):
        pages = []
    have_pages = any(isinstance(p, dict) and p.get("document_id") == doc.get("id") for p in pages)
    have_any_meta = len(existing_doc_metas) > 0

    if have_any_meta or have_pages:
        # ensure minimal metadata rows exist (populate from document fields if possible)
        def _upsert_meta(namespace, key, value=None, value_json=None):
            nonlocal metas
            for m in metas:
                if isinstance(m, dict) and m.get("document_id") == doc.get("id") and m.get("namespace") == namespace and m.get("key") == key:
                    m["value"] = value
                    m["value_json"] = value_json
                    m["updated_at"] = _now()
                    return
            metas.append({
                "id": _gen_id("meta", metas),
                "document_id": doc.get("id"),
                "namespace": namespace,
                "key": key,
                "value": value,
                "value_json": value_json,
                "created_at": _now(),
                "updated_at": _now(),
            })

        if doc.get("title"):
            _upsert_meta("dc", "title", doc.get("title"))
        if doc.get("author"):
            _upsert_meta("dc", "creator", doc.get("author"))
        if doc.get("language"):
            _upsert_meta("dc", "language", doc.get("language"))

        _save("document_metadata.json", metas)

        # transition ingesting -> ready
        if doc.get("status") == "ingesting" and "ready" in transitions.get("ingesting", []):
            doc["status"] = "ready"
            doc["ingest_error"] = None
            doc["updated_at"] = _now()
            _save("documents.json", docs)
    else:
        # transition ingesting -> error
        if doc.get("status") == "ingesting" and "error" in transitions.get("ingesting", []):
            doc["status"] = "error"
            doc["ingest_error"] = "EPUB metadata extraction unavailable offline: no existing metadata/pages for this document"
            doc["updated_at"] = _now()
            _save("documents.json", docs)

    # Return what we have
    metas = _load("document_metadata.json")
    if not isinstance(metas, list):
        metas = []
    rows = [m for m in metas if isinstance(m, dict) and m.get("document_id") == doc.get("id")]

    def _fmt(rows):
        out_lines = []
        grouped = {}
        for r in rows:
            ns = r.get("namespace") or "custom"
            grouped.setdefault(ns, []).append(r)
        for ns in sorted(grouped.keys()):
            out_lines.append(f"[{ns}]")
            for r in sorted(grouped[ns], key=lambda x: (str(x.get('key') or ""), str(x.get('id') or ""))):
                k = r.get("key")
                v = r.get("value")
                if v is None and r.get("value_json") is not None:
                    try:
                        v = json.dumps(r.get("value_json"), ensure_ascii=False)
                    except Exception:
                        v = str(r.get("value_json"))
                out_lines.append(f"{k}: {'' if v is None else v}")
            out_lines.append("")
        return "\n".join(out_lines).rstrip() + ("\n" if out_lines else "")

    _log("ok" if doc.get("status") != "error" else "error", None if doc.get("status") != "error" else "INTERNAL_ERROR", doc.get("ingest_error") if doc.get("status") == "error" else None, {"document_id": doc.get("id")})
    return {
        "data": {"document": doc, "metadata": rows, "formatted": _fmt(rows)},
        "meta": {"created_document": created, "timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000)},
    }

def read_epub_page_range(epub_path, start_page, end_page, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "read_epub_page_range"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, extra=None):
        # This service schema does not declare a request/audit log collection; do not fabricate persistent dynamics.
        return

    def _norm_path(p):
        s = str(p).strip()
        s = re.sub(r"[\\/]+", "/", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _path_hash(p):
        return hashlib.sha256(_norm_path(p).lower().encode("utf-8")).hexdigest()

    # Validate inputs
    if not isinstance(epub_path, str) or not epub_path.strip():
        _log("error", "VALIDATION_ERROR", "epub_path is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "epub_path is required and must be a non-empty string", param="epub_path")
    if not isinstance(start_page, int) or not isinstance(end_page, int):
        _log("error", "VALIDATION_ERROR", "start_page and end_page must be integers")
        return _err("VALIDATION_ERROR", "start_page and end_page must be integers", param=["start_page", "end_page"])
    if start_page > end_page:
        _log("error", "VALIDATION_ERROR", "start_page must be <= end_page")
        return _err("VALIDATION_ERROR", "start_page must be <= end_page", start_page=start_page, end_page=end_page)
    if start_page < 1 or end_page < 1:
        _log("error", "VALIDATION_ERROR", "page numbers must be >= 1")
        return _err("VALIDATION_ERROR", "page numbers must be >= 1", start_page=start_page, end_page=end_page)

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []
    pages_rows = _load("document_pages.json")
    if not isinstance(pages_rows, list):
        pages_rows = []

    # Resolve document by:
    # 1) id match (callers sometimes pass document_id as path)
    # 2) exact source_path match for doc_type=epub
    # 3) source_path_hash match for doc_type=epub
    norm = _norm_path(epub_path)
    h = _path_hash(norm)
    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("id") == epub_path:
            doc = d
            break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "epub" and _norm_path(d.get("source_path", "")) == norm:
                doc = d
                break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "epub" and d.get("source_path_hash") == h:
                doc = d
                break

    if doc is None or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", "EPUB not found")
        return _err("NOT_FOUND", "EPUB not found", epub_path=epub_path)

    # Must be ready for reads
    if doc.get("status") != "ready":
        _log("error", "CONFLICT", "document not ready")
        return _err("CONFLICT", "document not ready", document_id=doc.get("id"), status=doc.get("status"))

    requested = list(range(start_page, end_page + 1))

    # EPUB policy: requested pages must exist in document_pages for that document.
    # Also enforce consistent policy: fail if any requested page is missing or not extracted.
    by_num = {}
    for pr in pages_rows:
        if isinstance(pr, dict) and pr.get("document_id") == doc.get("id"):
            pn = pr.get("page_number")
            if isinstance(pn, int):
                by_num[pn] = pr

    missing = []
    not_extracted = []
    extracted = []
    for pn in requested:
        row = by_num.get(pn)
        if row is None:
            missing.append(pn)
            continue
        if row.get("status") != "extracted":
            not_extracted.append(pn)
            continue
        extracted.append(row)

    if missing or not_extracted:
        _log("error", "NOT_FOUND", "One or more requested pages are missing or not extracted")
        return _err(
            "NOT_FOUND",
            "One or more requested pages are missing or not extracted",
            document_id=doc.get("id"),
            missing_pages=sorted(missing),
            not_extracted_pages=sorted(not_extracted),
        )

    extracted.sort(key=lambda r: r.get("page_number", 0))
    # Format output: unique/sorted pages, each preceded with header
    chunks = []
    for r in extracted:
        pn = r.get("page_number")
        label = r.get("label")
        hdr = f"=== Page {pn}" + (f" ({label})" if isinstance(label, str) and label else "") + " ==="
        txt = r.get("text")
        if txt is None:
            txt = ""
        chunks.append(hdr + "\n" + txt)
    out = "\n\n".join(chunks)

    _log("ok")
    return {
        "document_id": doc.get("id"),
        "doc_type": doc.get("doc_type"),
        "source_path": doc.get("source_path"),
        "start_page": start_page,
        "end_page": end_page,
        "pages": requested,
        "text": out,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def read_epub_pages(epub_path, pages, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "read_epub_pages"

    def _log(status, code=None, message=None, extra=None):
        return

    def _norm_path(p):
        s = str(p).strip()
        s = re.sub(r"[\\/]+", "/", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _path_hash(p):
        return hashlib.sha256(_norm_path(p).lower().encode("utf-8")).hexdigest()

    # Validate inputs
    if not isinstance(epub_path, str) or not epub_path.strip():
        _log("error", "VALIDATION_ERROR", "epub_path is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "epub_path is required and must be a non-empty string", param="epub_path")
    if not isinstance(pages, list) or len(pages) == 0:
        _log("error", "VALIDATION_ERROR", "pages must be a non-empty array of integers")
        return _err("VALIDATION_ERROR", "pages must be a non-empty array of integers", param="pages")
    if any((not isinstance(p, int)) for p in pages):
        _log("error", "VALIDATION_ERROR", "pages must contain only integers")
        return _err("VALIDATION_ERROR", "pages must contain only integers", param="pages")
    if any(p < 1 for p in pages):
        _log("error", "VALIDATION_ERROR", "page numbers must be >= 1")
        return _err("VALIDATION_ERROR", "page numbers must be >= 1", param="pages")

    # Output must be unique & sorted; do not reject duplicates
    requested = sorted(set(pages))

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []
    pages_rows = _load("document_pages.json")
    if not isinstance(pages_rows, list):
        pages_rows = []

    norm = _norm_path(epub_path)
    h = _path_hash(norm)

    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("id") == epub_path:
            doc = d
            break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "epub" and _norm_path(d.get("source_path", "")) == norm:
                doc = d
                break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "epub" and d.get("source_path_hash") == h:
                doc = d
                break

    if doc is None or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", "EPUB not found")
        return _err("NOT_FOUND", "EPUB not found", epub_path=epub_path)

    if doc.get("status") != "ready":
        _log("error", "CONFLICT", "document not ready")
        return _err("CONFLICT", "document not ready", document_id=doc.get("id"), status=doc.get("status"))

    by_num = {}
    for pr in pages_rows:
        if isinstance(pr, dict) and pr.get("document_id") == doc.get("id"):
            pn = pr.get("page_number")
            if isinstance(pn, int):
                by_num[pn] = pr

    missing = []
    not_extracted = []
    extracted = []
    for pn in requested:
        row = by_num.get(pn)
        if row is None:
            missing.append(pn)
            continue
        if row.get("status") != "extracted":
            not_extracted.append(pn)
            continue
        extracted.append(row)

    if missing or not_extracted:
        _log("error", "NOT_FOUND", "One or more requested pages are missing or not extracted")
        return _err(
            "NOT_FOUND",
            "One or more requested pages are missing or not extracted",
            document_id=doc.get("id"),
            missing_pages=sorted(missing),
            not_extracted_pages=sorted(not_extracted),
        )

    extracted.sort(key=lambda r: r.get("page_number", 0))
    chunks = []
    for r in extracted:
        pn = r.get("page_number")
        label = r.get("label")
        hdr = f"=== Page {pn}" + (f" ({label})" if isinstance(label, str) and label else "") + " ==="
        txt = r.get("text")
        if txt is None:
            txt = ""
        chunks.append(hdr + "\n" + txt)
    out = "\n\n".join(chunks)

    _log("ok")
    return {
        "document_id": doc.get("id"),
        "doc_type": doc.get("doc_type"),
        "source_path": doc.get("source_path"),
        "pages": requested,
        "text": out,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_pdf_metadata(pdf_path, **_extra):
    import json, os, datetime, hashlib, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_pdf_metadata"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        rows = _load("request_logs.json")
        if isinstance(rows, list):
            return "request_logs.json", rows
        rows = _load("request_log.json")
        if isinstance(rows, list):
            return "request_log.json", rows
        return "request_logs.json", []

    def _log(status, code=None, message=None, extra=None):
        fname, logs = _ensure_request_log()
        rid = "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    def _norm_path(p):
        s = str(p).strip()
        s = re.sub(r"[\\/]+", "/", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _path_hash(p):
        return hashlib.sha256(_norm_path(p).lower().encode("utf-8")).hexdigest()

    def _filename_from_path(p):
        s = str(p).strip()
        for sep in ("#", "?"):
            if sep in s:
                s = s.split(sep, 1)[0]
        base = os.path.basename(s.rstrip("/"))
        return base or None

    def _gen_id(prefix, existing_rows):
        used = set()
        for r in existing_rows:
            if isinstance(r, dict) and isinstance(r.get("id"), str):
                used.add(r["id"])
        for _ in range(50):
            cand = prefix + "_" + hashlib.sha256(f"{prefix}|{time.time_ns()}|{os.getpid()}".encode("utf-8")).hexdigest()[:24]
            if cand not in used:
                return cand
        return prefix + "_" + hashlib.sha256(f"{prefix}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    # Validate
    if not isinstance(pdf_path, str) or not pdf_path.strip():
        _log("error", "VALIDATION_ERROR", "pdf_path is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "pdf_path is required and must be a non-empty string", param="pdf_path")

    pdf_path = pdf_path.strip()
    h = _path_hash(pdf_path)

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []

    # Resolve by hash OR exact path OR by id (common client usage)
    doc = None
    for r in docs:
        if isinstance(r, dict) and r.get("doc_type") == "pdf" and r.get("source_path_hash") == h:
            doc = r
            break
    if doc is None:
        for r in docs:
            if isinstance(r, dict) and r.get("doc_type") == "pdf" and r.get("source_path") == pdf_path:
                doc = r
                break
    if doc is None:
        for r in docs:
            if isinstance(r, dict) and r.get("doc_type") == "pdf" and r.get("id") == pdf_path:
                doc = r
                break

    created = False
    if doc is None:
        now = _now()
        doc_id = _gen_id("doc", docs)
        doc = {
            "id": doc_id,
            "doc_type": "pdf",
            "source_path": pdf_path,
            "source_path_hash": h,
            "filename": _filename_from_path(pdf_path),
            "title": None,
            "author": None,
            "language": None,
            "page_count": None,
            "file_size_bytes": None,
            "sha256": None,
            "status": "registered",
            "ingest_error": None,
            "created_at": now,
            "updated_at": now,
        }
        docs.append(doc)
        _save("documents.json", docs)
        created = True

    if doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", "document is deleted", {"document_id": doc.get("id")})
        return _err("NOT_FOUND", "PDF path cannot be resolved or file is not accessible", path=pdf_path)

    metas = _load("document_metadata.json")
    if not isinstance(metas, list):
        metas = []
    existing_doc_metas = [m for m in metas if isinstance(m, dict) and m.get("document_id") == doc.get("id")]

    if doc.get("status") in ("ready", "error") and existing_doc_metas:
        def _fmt(rows):
            out_lines = []
            grouped = {}
            for r in rows:
                ns = r.get("namespace") or "custom"
                grouped.setdefault(ns, []).append(r)
            for ns in sorted(grouped.keys()):
                out_lines.append(f"[{ns}]")
                for r in sorted(grouped[ns], key=lambda x: (str(x.get('key') or ""), str(x.get('id') or ""))):
                    k = r.get("key")
                    v = r.get("value")
                    if v is None and r.get("value_json") is not None:
                        try:
                            v = json.dumps(r.get("value_json"), ensure_ascii=False)
                        except Exception:
                            v = str(r.get("value_json"))
                    out_lines.append(f"{k}: {'' if v is None else v}")
                out_lines.append("")
            return "\n".join(out_lines).rstrip() + ("\n" if out_lines else "")

        _log("ok", None, None, {"document_id": doc.get("id")})
        return {
            "data": {"document": doc, "metadata": existing_doc_metas, "formatted": _fmt(existing_doc_metas)},
            "meta": {"created_document": created, "timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000)},
        }

    # Ingest pass: registered/error -> ingesting -> ready OR error
    transitions = {
        "registered": ["ingesting", "deleted"],
        "ingesting": ["ready", "error", "deleted"],
        "ready": ["error", "deleted"],
        "error": ["ingesting", "deleted"],
        "deleted": []
    }

    cur = doc.get("status")
    if cur in ("registered", "error"):
        if "ingesting" not in transitions.get(cur, []):
            _log("error", "INVALID_TRANSITION", "illegal transition to ingesting", {"from_status": cur, "to_status": "ingesting"})
            return _err("INVALID_TRANSITION", "Illegal status transition for ingestion", from_status=cur, to_status="ingesting")
        doc["status"] = "ingesting"
        doc["updated_at"] = _now()
        _save("documents.json", docs)

    pages = _load("document_pages.json")
    if not isinstance(pages, list):
        pages = []
    have_pages = any(isinstance(p, dict) and p.get("document_id") == doc.get("id") for p in pages)
    have_any_meta = len(existing_doc_metas) > 0

    if have_any_meta or have_pages:
        # Upsert minimal metadata from document fields if present
        def _upsert_meta(namespace, key, value=None, value_json=None):
            nonlocal metas
            for m in metas:
                if isinstance(m, dict) and m.get("document_id") == doc.get("id") and m.get("namespace") == namespace and m.get("key") == key:
                    m["value"] = value
                    m["value_json"] = value_json
                    m["updated_at"] = _now()
                    return
            metas.append({
                "id": _gen_id("meta", metas),
                "document_id": doc.get("id"),
                "namespace": namespace,
                "key": key,
                "value": value,
                "value_json": value_json,
                "created_at": _now(),
                "updated_at": _now(),
            })

        if doc.get("title"):
            _upsert_meta("pdf", "Title", doc.get("title"))
        if doc.get("author"):
            _upsert_meta("pdf", "Author", doc.get("author"))

        _save("document_metadata.json", metas)

        if doc.get("status") == "ingesting" and "ready" in transitions.get("ingesting", []):
            doc["status"] = "ready"
            doc["ingest_error"] = None
            doc["updated_at"] = _now()
            _save("documents.json", docs)
    else:
        if doc.get("status") == "ingesting" and "error" in transitions.get("ingesting", []):
            doc["status"] = "error"
            doc["ingest_error"] = "PDF metadata extraction unavailable offline: no existing metadata/pages for this document"
            doc["updated_at"] = _now()
            _save("documents.json", docs)

    metas = _load("document_metadata.json")
    if not isinstance(metas, list):
        metas = []
    rows = [m for m in metas if isinstance(m, dict) and m.get("document_id") == doc.get("id")]

    def _fmt(rows):
        out_lines = []
        grouped = {}
        for r in rows:
            ns = r.get("namespace") or "custom"
            grouped.setdefault(ns, []).append(r)
        for ns in sorted(grouped.keys()):
            out_lines.append(f"[{ns}]")
            for r in sorted(grouped[ns], key=lambda x: (str(x.get('key') or ""), str(x.get('id') or ""))):
                k = r.get("key")
                v = r.get("value")
                if v is None and r.get("value_json") is not None:
                    try:
                        v = json.dumps(r.get("value_json"), ensure_ascii=False)
                    except Exception:
                        v = str(r.get("value_json"))
                out_lines.append(f"{k}: {'' if v is None else v}")
            out_lines.append("")
        return "\n".join(out_lines).rstrip() + ("\n" if out_lines else "")

    _log("ok" if doc.get("status") != "error" else "error", None if doc.get("status") != "error" else "INTERNAL_ERROR", doc.get("ingest_error") if doc.get("status") == "error" else None, {"document_id": doc.get("id")})
    return {
        "data": {"document": doc, "metadata": rows, "formatted": _fmt(rows)},
        "meta": {"created_document": created, "timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000)},
    }

def read_pdf_page_range(pdf_path, start_page, end_page, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "read_pdf_page_range"

    def _log(status, code=None, message=None, extra=None):
        return

    def _norm_path(p):
        s = str(p).strip()
        s = re.sub(r"[\\/]+", "/", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _path_hash(p):
        return hashlib.sha256(_norm_path(p).lower().encode("utf-8")).hexdigest()

    # Validate inputs
    if not isinstance(pdf_path, str) or not pdf_path.strip():
        _log("error", "VALIDATION_ERROR", "pdf_path is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "pdf_path is required and must be a non-empty string", param="pdf_path")
    if not isinstance(start_page, int) or not isinstance(end_page, int):
        _log("error", "VALIDATION_ERROR", "start_page and end_page must be integers")
        return _err("VALIDATION_ERROR", "start_page and end_page must be integers", param=["start_page", "end_page"])
    if start_page > end_page:
        _log("error", "VALIDATION_ERROR", "start_page must be <= end_page")
        return _err("VALIDATION_ERROR", "start_page must be <= end_page", start_page=start_page, end_page=end_page)
    if start_page < 1 or end_page < 1:
        _log("error", "VALIDATION_ERROR", "page numbers must be >= 1")
        return _err("VALIDATION_ERROR", "page numbers must be >= 1", start_page=start_page, end_page=end_page)

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []
    pages_rows = _load("document_pages.json")
    if not isinstance(pages_rows, list):
        pages_rows = []

    norm = _norm_path(pdf_path)
    h = _path_hash(norm)

    doc = None
    # accept document id as "path"
    for d in docs:
        if isinstance(d, dict) and d.get("id") == pdf_path:
            doc = d
            break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "pdf" and _norm_path(d.get("source_path", "")) == norm:
                doc = d
                break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "pdf" and d.get("source_path_hash") == h:
                doc = d
                break

    # If caller passed an id of an EPUB (or other type), still allow reads by id for that document if it's ready.
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("id") == pdf_path:
                doc = d
                break

    if doc is None or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", "PDF not found")
        return _err("NOT_FOUND", "PDF not found", pdf_path=pdf_path)

    if doc.get("status") != "ready":
        _log("error", "CONFLICT", "document not ready")
        return _err("CONFLICT", "document not ready", document_id=doc.get("id"), status=doc.get("status"))

    # Enforce bounds when page_count is known
    pc = doc.get("page_count")
    if isinstance(pc, int):
        if start_page > pc or end_page > pc:
            _log("error", "VALIDATION_ERROR", "requested page is out of bounds")
            return _err(
                "VALIDATION_ERROR",
                "requested page is out of bounds",
                document_id=doc.get("id"),
                page_count=pc,
                start_page=start_page,
                end_page=end_page,
            )

    requested = list(range(start_page, end_page + 1))

    by_num = {}
    for pr in pages_rows:
        if isinstance(pr, dict) and pr.get("document_id") == doc.get("id"):
            pn = pr.get("page_number")
            if isinstance(pn, int):
                by_num[pn] = pr

    missing = []
    not_extracted = []
    extracted = []
    for pn in requested:
        row = by_num.get(pn)
        if row is None:
            missing.append(pn)
            continue
        if row.get("status") != "extracted":
            not_extracted.append(pn)
            continue
        extracted.append(row)

    if missing or not_extracted:
        _log("error", "NOT_FOUND", "One or more requested pages are missing or not extracted")
        return _err(
            "NOT_FOUND",
            "One or more requested pages are missing or not extracted",
            document_id=doc.get("id"),
            missing_pages=sorted(missing),
            not_extracted_pages=sorted(not_extracted),
        )

    extracted.sort(key=lambda r: r.get("page_number", 0))
    chunks = []
    for r in extracted:
        pn = r.get("page_number")
        label = r.get("label")
        hdr = f"=== Page {pn}" + (f" ({label})" if isinstance(label, str) and label else "") + " ==="
        txt = r.get("text")
        if txt is None:
            txt = ""
        chunks.append(hdr + "\n" + txt)
    out = "\n\n".join(chunks)

    _log("ok")
    return {
        "document_id": doc.get("id"),
        "doc_type": doc.get("doc_type"),
        "source_path": doc.get("source_path"),
        "start_page": start_page,
        "end_page": end_page,
        "pages": requested,
        "text": out,
        "latency_ms": int((time.time() - t0) * 1000),
    }

