def search_pdf(pdf_path, terms, **_extra):
    import json, os, datetime, hashlib, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_pdf"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        rows = _load("request_logs.json")
        if isinstance(rows, list):
            return "request_logs.json", rows
        rows = _load("request_log.json")
        if isinstance(rows, list):
            return "request_log.json", rows
        return "request_logs.json", []

    def _log(status, code=None, message=None, extra=None):
        fname, logs = _ensure_request_log()
        rid = "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    def _norm_path(p):
        s = str(p).strip()
        s = re.sub(r"[\\/]+", "/", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _path_hash(p):
        return hashlib.sha256(_norm_path(p).lower().encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    def _normalize_terms(s):
        parts = [p.strip().lower() for p in str(s).split(",")]
        parts = [p for p in parts if p]
        dedup = []
        seen = set()
        for p in parts:
            if p not in seen:
                seen.add(p)
                dedup.append(p)
        return dedup

    # Validate
    if not isinstance(pdf_path, str) or not pdf_path.strip():
        _log("error", "VALIDATION_ERROR", "pdf_path is required")
        return _err("VALIDATION_ERROR", "pdf_path is required", param="pdf_path")
    if not isinstance(terms, str) or not terms.strip():
        _log("error", "VALIDATION_ERROR", "terms is required")
        return _err("VALIDATION_ERROR", "terms is required", param="terms")

    pdf_path = pdf_path.strip()
    terms_raw = terms
    norm_terms = _normalize_terms(terms_raw)
    if len(norm_terms) < 1:
        _log("error", "VALIDATION_ERROR", "terms_normalized must have at least one term")
        return _err("VALIDATION_ERROR", "terms must contain at least one non-empty term", param="terms")

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []
    h = _path_hash(pdf_path)

    doc = None
    for r in docs:
        if isinstance(r, dict) and r.get("doc_type") == "pdf" and (r.get("source_path_hash") == h or r.get("source_path") == pdf_path or r.get("id") == pdf_path):
            doc = r
            break

    if doc is None or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", "PDF path could not be resolved", {"path": pdf_path})
        return _err("NOT_FOUND", "PDF path cannot be resolved or file is not accessible", path=pdf_path)

    if doc.get("status") != "ready":
        _log("error", "CONFLICT", "document not ready", {"document_id": doc.get("id"), "status": doc.get("status")})
        return _err("CONFLICT", "document not ready: text extraction pending", document_id=doc.get("id"), status=doc.get("status"))

    # Create search request (queued -> running -> succeeded/failed)
    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []
    sr_id = _new_id("srch")
    now = _now()
    sr = {
        "id": sr_id,
        "document_id": doc.get("id"),
        "terms_raw": terms_raw,
        "terms_normalized": norm_terms,
        "match_mode": "case_insensitive_contains",
        "status": "queued",
        "result_pages_count": None,
        "execution_ms": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    search_requests.append(sr)
    _save("search_requests.json", search_requests)

    transitions = {
        "queued": ["running", "failed"],
        "running": ["succeeded", "failed"],
        "succeeded": [],
        "failed": []
    }

    # Move to running
    if "running" not in transitions.get(sr["status"], []):
        sr["status"] = "failed"
        sr["error_message"] = "invalid search request transition policy"
        sr["updated_at"] = _now()
        _save("search_requests.json", search_requests)
        _log("error", "INVALID_TRANSITION", sr["error_message"], {"search_request_id": sr_id})
        return _err("INVALID_TRANSITION", sr["error_message"], search_request_id=sr_id)

    sr["status"] = "running"
    sr["updated_at"] = _now()
    _save("search_requests.json", search_requests)

    # Execute scan over extracted pages; if a requested page isn't extracted, fail the search (consistent with reads)
    pages_rows = _load("document_pages.json")
    if not isinstance(pages_rows, list):
        pages_rows = []

    doc_pages = [p for p in pages_rows if isinstance(p, dict) and p.get("document_id") == doc.get("id")]
    extracted_pages = [p for p in doc_pages if p.get("status") == "extracted"]

    start_exec = time.time()
    results = []
    for p in extracted_pages:
        text = p.get("text") or ""
        lt = text.lower()
        matched = []
        match_count = 0
        first_idx = None
        for term in norm_terms:
            idx = lt.find(term)
            if idx != -1:
                matched.append(term)
                # count occurrences (non-overlapping)
                count = lt.count(term)
                match_count += max(0, count)
                if first_idx is None or idx < first_idx:
                    first_idx = idx
        if matched and match_count >= 1:
            snippet = None
            if first_idx is not None:
                start = max(0, first_idx - 40)
                end = min(len(text), first_idx + 120)
                snippet = text[start:end].replace("\n", " ").strip()
            results.append({
                "page_number": p.get("page_number"),
                "matched_terms": matched,
                "match_count": match_count,
                "snippet": snippet
            })

    # Ensure immutability: since this is a new search_request, it's safe to insert; once succeeded/failed we won't modify.
    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []

    now2 = _now()
    for r in sorted(results, key=lambda x: int(x.get("page_number") or 0)):
        if not isinstance(r.get("page_number"), int) or r["page_number"] < 1:
            continue
        search_results.append({
            "id": _new_id("sres"),
            "search_request_id": sr_id,
            "document_id": doc.get("id"),
            "page_number": r["page_number"],
            "matched_terms": r["matched_terms"],
            "match_count": r["match_count"],
            "snippet": r["snippet"],
            "created_at": now2,
            "updated_at": now2,
        })
    _save("search_results.json", search_results)

    exec_ms = int((time.time() - start_exec) * 1000)

    # Move to succeeded
    if "succeeded" not in transitions.get(sr["status"], []):
        sr["status"] = "failed"
        sr["error_message"] = "invalid transition to succeeded"
    else:
        sr["status"] = "succeeded"
        sr["error_message"] = None
        sr["result_pages_count"] = len({r["page_number"] for r in results})
        sr["execution_ms"] = exec_ms
    sr["updated_at"] = _now()
    _save("search_requests.json", search_requests)

    formatted_lines = [f"Search terms: {', '.join(norm_terms)}", f"Document: {doc.get('id')}", ""]
    if results:
        for r in sorted(results, key=lambda x: x["page_number"]):
            formatted_lines.append(f"Page {r['page_number']}: {r['match_count']} match(es) [{', '.join(r['matched_terms'])}]")
            if r.get("snippet"):
                formatted_lines.append(f"  Snippet: {r['snippet']}")
    else:
        formatted_lines.append("No matches found.")

    _log("ok", None, None, {"document_id": doc.get("id"), "search_request_id": sr_id})
    return {
        "data": {
            "search_request": sr,
            "results": [r for r in search_results if isinstance(r, dict) and r.get("search_request_id") == sr_id],
            "formatted": "\n".join(formatted_lines).rstrip() + "\n",
        },
        "meta": {"timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000)},
    }

def search_epub(epub_path, terms, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_epub"

    def _log(status, code=None, message=None, extra=None):
        return

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_path(p):
        s = str(p).strip()
        s = re.sub(r"[\\/]+", "/", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _path_hash(p):
        return hashlib.sha256(_norm_path(p).lower().encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    def _normalize_terms(s):
        parts = [p.strip().lower() for p in str(s).split(",")]
        parts = [p for p in parts if p]
        seen = set()
        out = []
        for p in parts:
            if p not in seen:
                seen.add(p)
                out.append(p)
        return out

    def _transition_ok(cur, nxt):
        allowed = {
            "queued": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        return nxt in allowed.get(cur, set())

    # Validate
    if not isinstance(epub_path, str) or not epub_path.strip():
        _log("error", "VALIDATION_ERROR", "epub_path is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "epub_path is required and must be a non-empty string", param="epub_path")
    if not isinstance(terms, str) or not terms.strip():
        _log("error", "VALIDATION_ERROR", "terms is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "terms is required and must be a non-empty string", param="terms")

    norm = _norm_path(epub_path)
    h = _path_hash(norm)

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []
    pages_rows = _load("document_pages.json")
    if not isinstance(pages_rows, list):
        pages_rows = []
    sr = _load("search_requests.json")
    if not isinstance(sr, list):
        sr = []
    res = _load("search_results.json")
    if not isinstance(res, list):
        res = []

    # Resolve doc (id OR path/hash for epub)
    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("id") == epub_path:
            doc = d
            break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "epub" and _norm_path(d.get("source_path", "")) == norm:
                doc = d
                break
    if doc is None:
        for d in docs:
            if isinstance(d, dict) and d.get("doc_type") == "epub" and d.get("source_path_hash") == h:
                doc = d
                break

    if doc is None or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND", "EPUB not found")
        return _err("NOT_FOUND", "EPUB not found", epub_path=epub_path)

    # Create search request
    terms_norm = _normalize_terms(terms)
    if len(terms_norm) < 1:
        _log("error", "VALIDATION_ERROR", "terms must contain at least one non-empty term")
        return _err("VALIDATION_ERROR", "terms must contain at least one non-empty term", param="terms")

    search_id = _new_id("srch")
    created = _now()
    sr_row = {
        "id": search_id,
        "document_id": doc.get("id"),
        "terms_raw": terms,
        "terms_normalized": terms_norm,
        "match_mode": "case_insensitive_contains",
        "status": "queued",
        "result_pages_count": None,
        "execution_ms": None,
        "error_message": None,
        "created_at": created,
        "updated_at": created,
    }
    sr.append(sr_row)
    _save("search_requests.json", sr)

    # Must follow lifecycle transitions
    # queued -> running
    if not _transition_ok("queued", "running"):
        sr_row["status"] = "failed"
        sr_row["error_message"] = "invalid lifecycle transition"
        sr_row["updated_at"] = _now()
        _save("search_requests.json", sr)
        _log("error", "INVALID_TRANSITION", "invalid search request transition")
        return _err("INVALID_TRANSITION", "invalid search request transition", search_request_id=search_id)

    sr_row["status"] = "running"
    sr_row["updated_at"] = _now()
    _save("search_requests.json", sr)

    # Document must be ready to search (needs extracted text)
    if doc.get("status") != "ready":
        sr_row["status"] = "failed"
        sr_row["error_message"] = "document not ready: text extraction pending"
        sr_row["updated_at"] = _now()
        _save("search_requests.json", sr)
        _log("error", "CONFLICT", "document not ready")
        return _err("CONFLICT", "document not ready", document_id=doc.get("id"), status=doc.get("status"), search_request_id=search_id)

    # Build searchable pages (only extracted, with text)
    doc_pages = []
    for pr in pages_rows:
        if not isinstance(pr, dict):
            continue
        if pr.get("document_id") != doc.get("id"):
            continue
        if pr.get("status") != "extracted":
            continue
        txt = pr.get("text")
        if not isinstance(txt, str):
            continue
        pn = pr.get("page_number")
        if isinstance(pn, int) and pn >= 1:
            doc_pages.append(pr)
    doc_pages.sort(key=lambda r: r.get("page_number", 0))

    start_exec = time.time()

    # Scan & write results; ensure immutability is preserved by only writing for this new search_id.
    inserted = 0
    pages_with_matches = 0
    for pr in doc_pages:
        txt_l = pr.get("text", "").lower()
        matched_terms = []
        match_count = 0
        first_idx = None
        for term in terms_norm:
            if not term:
                continue
            # count occurrences
            idx = 0
            term_count = 0
            while True:
                j = txt_l.find(term, idx)
                if j < 0:
                    break
                term_count += 1
                if first_idx is None or j < first_idx:
                    first_idx = j
                idx = j + max(1, len(term))
            if term_count > 0:
                matched_terms.append(term)
                match_count += term_count

        if match_count >= 1 and len(matched_terms) >= 1:
            pages_with_matches += 1
            snippet = None
            if first_idx is not None:
                raw = pr.get("text", "")
                lo = max(0, first_idx - 40)
                hi = min(len(raw), first_idx + 80)
                snippet = raw[lo:hi].strip() if isinstance(raw, str) else None

            res_row = {
                "id": _new_id("sres"),
                "search_request_id": search_id,
                "document_id": doc.get("id"),
                "page_number": pr.get("page_number"),
                "matched_terms": matched_terms,
                "match_count": match_count,
                "snippet": snippet,
                "created_at": _now(),
                "updated_at": _now(),
            }
            res.append(res_row)
            inserted += 1

    _save("search_results.json", res)

    exec_ms = int((time.time() - start_exec) * 1000)

    # running -> succeeded
    if not _transition_ok("running", "succeeded"):
        sr_row["status"] = "failed"
        sr_row["error_message"] = "invalid lifecycle transition"
        sr_row["updated_at"] = _now()
        _save("search_requests.json", sr)
        _log("error", "INVALID_TRANSITION", "invalid search request transition")
        return _err("INVALID_TRANSITION", "invalid search request transition", search_request_id=search_id)

    sr_row["status"] = "succeeded"
    sr_row["result_pages_count"] = pages_with_matches
    sr_row["execution_ms"] = exec_ms
    sr_row["updated_at"] = _now()
    _save("search_requests.json", sr)

    # Return formatted results
    # Group by page_number (unique already by insert policy, but be safe)
    results = [r for r in res if isinstance(r, dict) and r.get("search_request_id") == search_id]
    results.sort(key=lambda r: r.get("page_number", 0))

    lines = []
    for r in results:
        pn = r.get("page_number")
        mt = r.get("matched_terms") or []
        mc = r.get("match_count")
        sn = r.get("snippet")
        lines.append(f"- Page {pn}: {mc} match(es) [{', '.join(mt)}]" + (f"\n  {sn}" if isinstance(sn, str) and sn else ""))

    _log("ok")
    return {
        "search_request": sr_row,
        "result_pages_count": pages_with_matches,
        "results": results,
        "formatted": "\n".join(lines),
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_documents(doc_type=None, status=None, source_path_hash=None, q=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation
    if doc_type is not None and (not isinstance(doc_type, str) or doc_type not in ("pdf", "epub")):
        return _err("VALIDATION_ERROR", "Invalid doc_type. Expected one of: pdf, epub.")
    if status is not None and (not isinstance(status, str) or status not in ("registered", "ingesting", "ready", "error", "deleted")):
        return _err("VALIDATION_ERROR", "Invalid status. Expected one of: registered, ingesting, ready, error, deleted.")
    if source_path_hash is not None:
        if not isinstance(source_path_hash, str) or len(source_path_hash) == 0:
            return _err("VALIDATION_ERROR", "source_path_hash must be a non-empty string.")
        # best-effort hex validation (allow any case)
        if not re.fullmatch(r"[0-9a-fA-F]+", source_path_hash):
            return _err("VALIDATION_ERROR", "source_path_hash must be a hex string.")
    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string.")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "Invalid page. Must be an integer >= 1.", param="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "Invalid page_size. Must be an integer between 1 and 200.", param="page_size")

    # Load
    docs = _load("documents.json")

    # Filter
    filtered = []
    qn = q.lower().strip() if isinstance(q, str) else None
    for d in docs if isinstance(docs, list) else []:
        if not isinstance(d, dict):
            continue
        if doc_type is not None and d.get("doc_type") != doc_type:
            continue
        if status is not None and d.get("status") != status:
            continue
        if source_path_hash is not None and d.get("source_path_hash") != source_path_hash:
            continue
        if qn:
            hay = []
            for f in ("filename", "title", "author"):
                v = d.get(f)
                if isinstance(v, str) and v:
                    hay.append(v.lower())
            if not hay or qn not in " ".join(hay):
                continue
        filtered.append(d)

    # Sort by updated_at desc (fallback created_at)
    def _ts(v):
        s = v.get("updated_at") or v.get("created_at") or ""
        return s if isinstance(s, str) else ""
    filtered.sort(key=_ts, reverse=True)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    if start > total and total != 0:
        return _err("VALIDATION_ERROR", "INVALID_PAGE: page is out of range.", code_detail="INVALID_PAGE")

    items = filtered[start:end] if start < total else []

    has_more = end < total
    next_page = (page + 1) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": items,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": next_page
        },
        "meta": {
            "timestamp": now,
            "latency_ms": latency_ms
        }
    }

