def create_document(doc_type, source_path, filename=None, title=None, author=None, language=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation
    if not isinstance(doc_type, str) or doc_type not in ("pdf", "epub"):
        return _err("VALIDATION_ERROR", "Invalid doc_type. Expected one of: pdf, epub.", param="doc_type")
    if not isinstance(source_path, str) or len(source_path.strip()) == 0:
        return _err("VALIDATION_ERROR", "source_path is required and must be a non-empty string.", param="source_path")
    for nm, val in (("filename", filename), ("title", title), ("author", author), ("language", language)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string if provided.", param=nm)

    # Normalize and hash
    norm = source_path.strip()
    source_path_hash = hashlib.sha256(norm.encode("utf-8")).hexdigest()

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []

    # Unique(doc_type, source_path_hash): reuse if exists
    existing = None
    for d in docs:
        if isinstance(d, dict) and d.get("doc_type") == doc_type and d.get("source_path_hash") == source_path_hash:
            existing = d
            break

    if existing is not None:
        # Conflict if same hash but different stored source_path (shouldn't happen if hash is of normalized path)
        if isinstance(existing.get("source_path"), str) and existing.get("source_path") != norm:
            return _err(
                "CONFLICT",
                "A document with the same (doc_type, source_path_hash) already exists but maps to a different source_path.",
                existing_document_id=existing.get("id"),
                existing_source_path=existing.get("source_path"),
                provided_source_path=norm
            )
        # Idempotent: return existing record unchanged (optionally could update nullable fields, but spec says return existing)
        latency_ms = int((time.time() - t0) * 1000)
        return {"data": existing, "meta": {"timestamp": now, "latency_ms": latency_ms, "idempotent": True}}

    # Generate id
    def _new_id():
        # doc_<yyyymmddhhmmss>_<rand>
        import secrets
        return "doc_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + secrets.token_hex(8)

    doc_id = _new_id()

    # Best-effort filename if not provided
    inferred_filename = None
    try:
        inferred_filename = os.path.basename(norm)
        if inferred_filename == "":
            inferred_filename = None
    except Exception:
        inferred_filename = None

    rec = {
        "id": doc_id,
        "doc_type": doc_type,
        "source_path": norm,
        "source_path_hash": source_path_hash,
        "filename": filename if filename is not None else inferred_filename,
        "title": title,
        "author": author,
        "language": language,
        "page_count": None,
        "file_size_bytes": None,
        "sha256": None,
        "status": "registered",
        "ingest_error": None,
        "created_at": now,
        "updated_at": now
    }

    docs.append(rec)
    _save("documents.json", docs)

    latency_ms = int((time.time() - t0) * 1000)
    return {"data": rec, "meta": {"timestamp": now, "latency_ms": latency_ms}}

def update_document(id, status=None, title=None, author=None, language=None, ingest_error=None, **_extra):
