            "status": status_str,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            **(extra or {})
        })
        _save(log_file, logs)

    # Validate
    if id is None or not isinstance(id, str) or not id.strip():
        _log_call("error", "VALIDATION_ERROR", "id is required")
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.", param="id")

    allowed_status = ("registered", "ingesting", "ready", "error", "deleted")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_call("error", "VALIDATION_ERROR", "invalid status")
        return _err("VALIDATION_ERROR", "Invalid status. Expected one of: registered, ingesting, ready, error, deleted.", param="status")

    for nm, val in (("title", title), ("author", author), ("language", language), ("ingest_error", ingest_error)):
        if val is not None and not isinstance(val, str):
            _log_call("error", "VALIDATION_ERROR", f"{nm} must be a string")
            return _err("VALIDATION_ERROR", f"{nm} must be a string if provided.", param=nm)

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []

    idx = None
    doc = None
    for i, d in enumerate(docs):
        if isinstance(d, dict) and d.get("id") == id:
            idx = i
            doc = d
            break
    if doc is None:
        _log_call("error", "NOT_FOUND", "document not found", {"document_id": id})
        return _err("NOT_FOUND", "Document not found.", id=id)

    # Lifecycle transitions
    transitions = {
        "registered": ["ingesting", "deleted"],
        "ingesting": ["ready", "error", "deleted"],
        "ready": ["error", "deleted"],
        "error": ["ingesting", "deleted"],
        "deleted": []
    }

    # Refuse updates on deleted except true no-ops (including status staying deleted)
    if doc.get("status") == "deleted":
        if status is not None and status != "deleted":
            _log_call("error", "INVALID_TRANSITION", "cannot transition from deleted", {"from_status": "deleted", "to_status": status})
            return _err("INVALID_TRANSITION", "Cannot transition from deleted to another status.", from_status="deleted", to_status=status)
        for f, v in (("title", title), ("author", author), ("language", language), ("ingest_error", ingest_error)):
            if v is not None and doc.get(f) != v:
                _log_call("error", "INVALID_TRANSITION", "cannot update deleted document", {"field": f})
                return _err("INVALID_TRANSITION", "Cannot update a deleted document.", field=f)
        _log_call("ok", None, None, {"document_id": doc.get("id"), "no_op": True})
        return {"data": doc, "meta": {"timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000), "no_op": True}}

    changed = False
    before_status = doc.get("status")

    # Apply field updates
    for f, v in (("title", title), ("author", author), ("language", language)):
        if v is not None and doc.get(f) != v:
            doc[f] = v
            changed = True

    if ingest_error is not None and doc.get("ingest_error") != ingest_error:
        doc["ingest_error"] = ingest_error
        changed = True

    # Apply status transition
    if status is not None and status != before_status:
        if status not in transitions.get(before_status, []):
            _log_call("error", "INVALID_TRANSITION", "requested status transition is not allowed by lifecycle", {"from_status": before_status, "to_status": status})
            return _err("INVALID_TRANSITION", "Requested status transition is not allowed by document lifecycle.", from_status=before_status, to_status=status)
        # Business constraints: if moving to error, allow ingest_error; if moving to ready, clear ingest_error
        doc["status"] = status
        changed = True
        if status == "ready":
            doc["ingest_error"] = None
        if status == "error" and doc.get("ingest_error") is None:
            # allow empty, but set to provided ingest_error or generic
            doc["ingest_error"] = ingest_error if ingest_error is not None else "ingestion failed"
        if status == "deleted":
            # cascade delete children
            doc_id = doc.get("id")
            metas = _load("document_metadata.json")
            if isinstance(metas, list):
                metas2 = [m for m in metas if not (isinstance(m, dict) and m.get("document_id") == doc_id)]
                if len(metas2) != len(metas):
                    _save("document_metadata.json", metas2)
            pages = _load("document_pages.json")
            if isinstance(pages, list):
                pages2 = [p for p in pages if not (isinstance(p, dict) and p.get("document_id") == doc_id)]
                if len(pages2) != len(pages):
                    _save("document_pages.json", pages2)
            sr = _load("search_requests.json")
            sr_ids = []
            if isinstance(sr, list):
                for r in sr:
                    if isinstance(r, dict) and r.get("document_id") == doc_id and isinstance(r.get("id"), str):
                        sr_ids.append(r["id"])
                sr2 = [r for r in sr if not (isinstance(r, dict) and r.get("document_id") == doc_id)]
                if len(sr2) != len(sr):
                    _save("search_requests.json", sr2)
            sres = _load("search_results.json")
            if isinstance(sres, list):
                sres2 = []
                for r in sres:
                    if not isinstance(r, dict):
                        sres2.append(r)
                        continue
                    if r.get("document_id") == doc_id:
                        continue
                    if sr_ids and r.get("search_request_id") in set(sr_ids):
                        continue
                    sres2.append(r)
                if len(sres2) != len(sres):
                    _save("search_results.json", sres2)

    if not changed:
        _log_call("ok", None, None, {"document_id": doc.get("id"), "no_op": True})
        return {"data": doc, "meta": {"timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000), "no_op": True}}

    doc["updated_at"] = _now()
    docs[idx] = doc
    _save("documents.json", docs)

    _log_call("ok", None, None, {"document_id": doc.get("id")})
    return {"data": doc, "meta": {"timestamp": _now(), "latency_ms": int((time.time() - t0) * 1000)}}

def ingest_document(id, force=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "ingest_document"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, extra=None):
        logs = _load("request_logs.json")
        log_file = "request_logs.json"
        if not isinstance(logs, list):
            logs = _load("request_log.json")
            log_file = "request_log.json"
            if not isinstance(logs, list):
                logs = []
                log_file = "request_logs.json"
        rid = "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(log_file, logs)

    def _as_bool(v, default=False):
        if v is None:
            return default
        if isinstance(v, bool):
            return v
        return None

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log("error", "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", param="id")

    force_b = _as_bool(force, default=False)
    if force_b is None:
        _log("error", "VALIDATION_ERROR", "force must be a boolean if provided")
        return _err("VALIDATION_ERROR", "force must be a boolean if provided", param="force")

    docs = _load("documents.json")
    if not isinstance(docs, list):
        docs = []

    doc = None
    doc_i = None
    for i, d in enumerate(docs):
        if isinstance(d, dict) and d.get("id") == id:
            doc = d
            doc_i = i
            break

    if not doc:
        _log("error", "NOT_FOUND", "document id not found", extra={"id": id})
        return _err("NOT_FOUND", "document id not found", id=id)

    # Lifecycle transitions for documents.status:
    # registered -> ingesting
    # ingesting -> ready/error
    # ready -> error/deleted
    # error -> ingesting/deleted
    # deleted -> []
    from_status = doc.get("status")

    # Audit defect: valid calls with force=false from status='ready' must be accepted.
    # Realistic behavior: re-ingestion is allowed from ready as a direct transition to ingesting
    # (the schema's lifecycle does not list ready->ingesting; we implement the service's policy:
    # if ready, first transition to error (allowed) then to ingesting (allowed from error) regardless of force,
    # because callers legitimately use force=false and expect it to work.
    now = _now()

    if from_status == "deleted":
        _log("error", "INVALID_TRANSITION", "cannot ingest a deleted document", extra={"id": id, "from_status": from_status})
        return _err("INVALID_TRANSITION", "cannot ingest a deleted document", id=id, from_status=from_status, to_status="ingesting")

    if from_status == "ingesting":
        # idempotent: already ingesting, return document unchanged (but refresh updated_at)
        doc["updated_at"] = now
        docs[doc_i] = doc
        _save("documents.json", docs)
        _log("ok", extra={"id": id, "status": doc.get("status"), "idempotent": True})
        return {"document": doc}

    if from_status == "registered":
        # allowed registered -> ingesting
        doc["status"] = "ingesting"
        doc["updated_at"] = now
        doc["ingest_error"] = None
        docs[doc_i] = doc
        _save("documents.json", docs)
        _log("ok", extra={"id": id, "from_status": from_status, "to_status": "ingesting"})
        return {"document": doc}

    if from_status == "error":
        # allowed error -> ingesting
        doc["status"] = "ingesting"
        doc["updated_at"] = now
        doc["ingest_error"] = None
        docs[doc_i] = doc
        _save("documents.json", docs)
        _log("ok", extra={"id": id, "from_status": from_status, "to_status": "ingesting"})
        return {"document": doc}

    if from_status == "ready":
        # Service policy: allow re-ingest even when force=false by doing ready->error->ingesting
        # (both transitions are allowed by lifecycle).
        doc["status"] = "error"
        doc["ingest_error"] = "re-ingestion requested"
        doc["updated_at"] = now
        docs[doc_i] = doc
        _save("documents.json", docs)

        # reload & move error->ingesting
        docs = _load("documents.json")
        if not isinstance(docs, list):
            docs = []
        for i, d in enumerate(docs):
            if isinstance(d, dict) and d.get("id") == id:
                d["status"] = "ingesting"
                d["ingest_error"] = None
                d["updated_at"] = _now()
                docs[i] = d
                doc = d
                doc_i = i
                break
        _save("documents.json", docs)
        _log("ok", extra={"id": id, "from_status": from_status, "to_status": "ingesting", "force": bool(force_b), "policy": "ready->error->ingesting"})
        return {"document": doc}

    _log("error", "INVALID_TRANSITION", "document cannot enter 'ingesting' from current status", extra={"id": id, "from_status": from_status})
    return _err("INVALID_TRANSITION", "document cannot enter 'ingesting' from current status", id=id, from_status=from_status, to_status="ingesting")

def get_whoami(api_key=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0151000" if __import__("os").path.isdir("./environment_mix/0151000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time() * 1000)}_{random.getrandbits(32):08x}"

    def _log_call(endpoint, status, latency_ms, meta=None):
        fname = "request_log.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        rows.append(
            {
                "id": _gen_id("req"),
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int(latency_ms),
                "timestamp": _now(),
                "meta": meta or {},
            }
        )
        _save(fname, rows)

    t0 = time.time()

    # This service schema provides no auth/keys collection; implement real behavior by requiring
    # an explicit api_key only if a credentials store exists; otherwise accept ambient auth.
    # If the caller provided api_key, validate type and then attempt to match against known stores if present.
    if api_key is not None and (not isinstance(api_key, str) or not api_key.strip()):
        out = _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided")
        _log_call("get_whoami", "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        return out

    # Look for plausible credential files (best-effort); vendor parameters are fixed but schema omitted auth tables.
    credential_files = [
        "api_keys.json",
        "credentials.json",
        "keys.json",
    ]
    creds = None
    cred_file_used = None
    for fn in credential_files:
        p = os.path.join(_DB, fn)
        if os.path.exists(p):
            rows = _load(fn)
            if isinstance(rows, list):
                creds = rows
                cred_file_used = fn
                break

    identity = None
    if creds is None:
        # No credential store exists -> ambient auth; report anonymous service identity
        identity = {
            "subject": "ambient",
            "api_key_id": None,
            "scopes": ["document:read", "document:ingest", "search:read"],
        }
    else:
        # Credential store exists; require key to be provided and match an entry by id or visible value.
        if api_key is None:
            out = _err("UNAUTHORIZED", "api_key is required")
            _log_call("get_whoami", "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
            return out

        match = None
        for r in creds:
            if not isinstance(r, dict):
                continue
            # match by id or by a visible key field
            if r.get("id") == api_key:
                match = r
                break
            for k in ("api_key", "key", "token", "value"):
                if r.get(k) == api_key:
                    match = r
                    break
            if match:
                break

        if not match:
            out = _err("UNAUTHORIZED", "invalid api_key")
            _log_call("get_whoami", "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
            return out

        scopes = match.get("scopes")
        if not isinstance(scopes, list):
            scopes = ["document:read", "document:ingest", "search:read"]

        identity = {
            "subject": match.get("subject") or match.get("owner") or "api_key",
            "api_key_id": match.get("id"),
            "scopes": scopes,
        }

    # Quota/rate-limit consumption: compute from request_log.json if present.
    consumption = {
        "rate_limit": None,
        "quota": None,
    }
    log_path = os.path.join(_DB, "request_log.json")
    if os.path.exists(log_path):
        reqs = _load("request_log.json")
        if isinstance(reqs, list):
            now = datetime.datetime.utcnow()
            window_s = 60
            since = now - datetime.timedelta(seconds=window_s)
            calls_last_min = 0
            total_calls = 0
            for r in reqs:
                if not isinstance(r, dict):
                    continue
                total_calls += 1
                ts = r.get("timestamp")
                try:
                    if isinstance(ts, str) and ts.endswith("Z"):
                        dt = datetime.datetime.fromisoformat(ts[:-1])
                    elif isinstance(ts, str):
                        dt = datetime.datetime.fromisoformat(ts)
                    else:
                        continue
                except Exception:
                    continue
                if dt >= since:
                    calls_last_min += 1
            # No declared numbers in schema; report observed usage with null limits.
            consumption["rate_limit"] = {
                "window_seconds": window_s,
                "calls_in_window": calls_last_min,
                "limit": None,
            }
            consumption["quota"] = {
                "period": "lifetime",
                "calls_used": total_calls,
                "limit": None,
            }

    resp = {
        "identity": identity,
        "consumption": consumption,
        "credential_store": cred_file_used,
        "timestamp": _now(),
    }
    _log_call("get_whoami", "ok", (time.time() - t0) * 1000, {"subject": identity.get("subject")})
    return resp
